/**
 * Shared data-integrity validation for data/seed-statutes.json.
 *
 * Used by both the vitest suite (src/__tests__/seed-statutes-integrity.test.ts)
 * and the seeder pre-flight (src/seed-statutes.ts) so the two can never drift.
 * The seed is regenerated by scripts and merged from multiple sources; these
 * checks catch placeholder text, dropped sections (e.g. 498A), wrong counts,
 * and repeal notices standing in for real IPC text before anything hits the DB.
 */

export interface StatuteSeedRow {
  code: string;
  jurisdiction: string;
  section: string;
  heading: string;
  text: string;
}

export const EXPECTED_COUNTS: Record<string, number> = {
  BNS: 358,
  BNSS: 531,
  BSA: 170,
  IPC: 521,
  USC: 8,
  CRPC: 510,
  IEA: 181,
};

export const MIN_TEXT_LENGTH = 40;

// Real sections whose full official text is legitimately shorter than
// MIN_TEXT_LENGTH (e.g. IEA 75: "All other documents are private.").
export const KNOWN_SHORT_SECTIONS = new Set(["IEA::75"]);

export const PLACEHOLDER_PATTERNS: RegExp[] = [
  /full historical .* text is not included/i,
  /text (is )?not (included|available)/i,
  /placeholder/i,
  /\[?text omitted\]?/i,
  /to be added/i,
  /lorem ipsum/i,
  /TODO/,
];

// Repeal/omission notices must not replace actual IPC section text.
export const IPC_REPEAL_PATTERNS: RegExp[] = [
  /^\s*\[?(repealed|omitted)\b/i,
  /has been repealed and replaced/i,
  /refer to the (BNS|Bharatiya Nyaya Sanhita)/i,
];

export const KEY_IPC_SECTIONS = ["302", "420", "498A", "124A", "376(3)"];

function label(r: StatuteSeedRow): string {
  return `${r.code} ${r.section}`;
}

export interface IntegrityCheckResult {
  name: string;
  errors: string[];
}

export function checkTotalCount(rows: StatuteSeedRow[]): IntegrityCheckResult {
  const expectedTotal = Object.values(EXPECTED_COUNTS).reduce((a, b) => a + b, 0);
  return {
    name: "total row count",
    errors:
      rows.length === expectedTotal
        ? []
        : [`expected ${expectedTotal} rows, got ${rows.length}`],
  };
}

export function checkPerCodeCounts(rows: StatuteSeedRow[]): IntegrityCheckResult {
  const counts: Record<string, number> = {};
  for (const r of rows) counts[r.code] = (counts[r.code] ?? 0) + 1;
  const errors: string[] = [];
  for (const [code, expected] of Object.entries(EXPECTED_COUNTS)) {
    const actual = counts[code] ?? 0;
    if (actual !== expected) errors.push(`${code}: expected ${expected}, got ${actual}`);
  }
  for (const code of Object.keys(counts)) {
    if (!(code in EXPECTED_COUNTS)) errors.push(`unexpected code ${code}: ${counts[code]} rows`);
  }
  return { name: "per-code row counts", errors };
}

export function checkDuplicates(rows: StatuteSeedRow[]): IntegrityCheckResult {
  const seen = new Set<string>();
  const dupes: string[] = [];
  for (const r of rows) {
    const key = `${r.code}::${r.section}`;
    if (seen.has(key)) dupes.push(label(r));
    seen.add(key);
  }
  return { name: "duplicate (code, section) pairs", errors: dupes };
}

export function checkShortText(rows: StatuteSeedRow[]): IntegrityCheckResult {
  return {
    name: "empty or very short section text",
    errors: rows
      .filter(
        (r) =>
          (r.text ?? "").trim().length < MIN_TEXT_LENGTH &&
          !KNOWN_SHORT_SECTIONS.has(`${r.code}::${r.section}`),
      )
      .map((r) => `${label(r)} (${(r.text ?? "").trim().length} chars)`),
  };
}

export function checkEmptyHeadings(rows: StatuteSeedRow[]): IntegrityCheckResult {
  return {
    name: "empty headings",
    errors: rows.filter((r) => !(r.heading ?? "").trim()).map(label),
  };
}

export function checkPlaceholderText(rows: StatuteSeedRow[]): IntegrityCheckResult {
  return {
    name: "placeholder text",
    errors: rows
      .filter((r) => PLACEHOLDER_PATTERNS.some((p) => p.test(r.text)))
      .map(label),
  };
}

export function checkIpcRepealText(rows: StatuteSeedRow[]): IntegrityCheckResult {
  return {
    name: "repeal-notice text standing in for real IPC section text",
    errors: rows
      .filter((r) => r.code === "IPC" && IPC_REPEAL_PATTERNS.some((p) => p.test(r.text)))
      .map(label),
  };
}

export function checkKeyIpcSections(rows: StatuteSeedRow[]): IntegrityCheckResult {
  const ipcSections = new Set(rows.filter((r) => r.code === "IPC").map((r) => r.section));
  return {
    name: "missing key IPC sections",
    errors: KEY_IPC_SECTIONS.filter((s) => !ipcSections.has(s)),
  };
}

// ---------------------------------------------------------------------------
// Constitution of India (COI) seed checks — data/seed-constitution.json
// ---------------------------------------------------------------------------

export interface CoiSeedRow extends StatuteSeedRow {
  provisionType?: string;
}

export const COI_EXPECTED_TOTAL = 477; // preamble + 464 articles + 12 schedules
export const COI_EXPECTED_SCHEDULES = 12;
export const KEY_COI_ARTICLES = [
  "14",
  "19",
  "21",
  "21A",
  "32",
  "51A",
  "226",
  "243G",
  "300A",
  "356",
  "368",
  "370",
];
// Real articles whose full official text is legitimately short
// (e.g. Art. 52: "There shall be a President of India.").
export const KNOWN_SHORT_COI = new Set(["COI::52"]);

export function checkCoiTotalCount(rows: CoiSeedRow[]): IntegrityCheckResult {
  return {
    name: "COI total row count",
    errors:
      rows.length === COI_EXPECTED_TOTAL
        ? []
        : [`expected ${COI_EXPECTED_TOTAL} rows, got ${rows.length}`],
  };
}

export function checkCoiCode(rows: CoiSeedRow[]): IntegrityCheckResult {
  return {
    name: "COI code/jurisdiction tags",
    errors: rows
      .filter((r) => r.code !== "COI" || r.jurisdiction !== "IN")
      .map(label),
  };
}

export function checkCoiSchedules(rows: CoiSeedRow[]): IntegrityCheckResult {
  const scheds = rows.filter((r) => r.section.startsWith("SCH-"));
  const errors: string[] = [];
  if (scheds.length !== COI_EXPECTED_SCHEDULES)
    errors.push(`expected ${COI_EXPECTED_SCHEDULES} schedules, got ${scheds.length}`);
  for (const s of scheds) {
    if ((s.text ?? "").trim().length < 200)
      errors.push(`${label(s)} schedule text suspiciously short`);
  }
  return { name: "COI schedules", errors };
}

export function checkKeyCoiArticles(rows: CoiSeedRow[]): IntegrityCheckResult {
  const sections = new Set(rows.map((r) => r.section));
  return {
    name: "missing key COI articles",
    errors: KEY_COI_ARTICLES.filter((a) => !sections.has(a)),
  };
}

export function checkCoiShortText(rows: CoiSeedRow[]): IntegrityCheckResult {
  return {
    name: "COI empty or very short article text",
    errors: rows
      .filter(
        (r) =>
          (r.text ?? "").trim().length < MIN_TEXT_LENGTH &&
          !KNOWN_SHORT_COI.has(`${r.code}::${r.section}`),
      )
      .map((r) => `${label(r)} (${(r.text ?? "").trim().length} chars)`),
  };
}

/** Run all COI integrity checks. Returns only the checks that failed. */
export function validateConstitutionSeed(rows: CoiSeedRow[]): IntegrityCheckResult[] {
  return [
    checkCoiTotalCount(rows),
    checkCoiCode(rows),
    checkCoiSchedules(rows),
    checkKeyCoiArticles(rows),
    checkCoiShortText(rows),
    checkDuplicates(rows),
    checkEmptyHeadings(rows),
    checkPlaceholderText(rows),
  ].filter((c) => c.errors.length > 0);
}

/** Run all integrity checks. Returns only the checks that failed. */
export function validateStatutesSeed(rows: StatuteSeedRow[]): IntegrityCheckResult[] {
  return [
    checkTotalCount(rows),
    checkPerCodeCounts(rows),
    checkDuplicates(rows),
    checkShortText(rows),
    checkEmptyHeadings(rows),
    checkPlaceholderText(rows),
    checkIpcRepealText(rows),
    checkKeyIpcSections(rows),
  ].filter((c) => c.errors.length > 0);
}
